// R5 frozen scalar joint-observer exact Bellman: 12-pair and 13-single extensions.
// Input: window_adj.bin made by pinned make_adj.py from SHA256
// 50e87f0194cfb3780e84b7bbb6f9a2dca4f79bb4901cab06f1a5b59256fb470b.
#include <bits/stdc++.h>
using namespace std;
static constexpr int N=256,Q=101;
static constexpr int S10[]={0,16,32,48,1,64,17,80,18,24};
static constexpr int S12[]={0,16,32,48,1,64,17,80,18,24,34,82};
struct A {int cost;vector<int> mask;};
using Sig=vector<A>;
vector<int> maximal(vector<int> v){sort(v.begin(),v.end());v.erase(unique(v.begin(),v.end()),v.end());vector<int> res;for(int s:v){bool sub=false;for(int t:v)if(s!=t&&(s&t)==s){sub=true;break;}if(!sub)res.push_back(s);}return res;}
Sig build(const vector<uint8_t>&adj,const vector<int>&h){const int n=h.size(),full=(1<<n)-1;map<vector<int>,int> cheapest;for(int q=0;q<Q;q++){const uint8_t *p=adj.data()+(size_t)q*N*N;vector<int> cand;for(int i=0;i<n;i++){int m=0;for(int j=0;j<n;j++)if(p[h[i]*N+h[j]])m|=1<<j;cand.push_back(m);}auto fam=maximal(move(cand));if(fam.size()==1&&fam[0]==full)continue;cheapest.emplace(fam,214+q);}Sig out;for(auto&[m,k]:cheapest)out.push_back({k,m});sort(out.begin(),out.end(),[](const A&a,const A&b){return a.cost<b.cost;});return out;}
string sigkey(const Sig&a){string s;for(const A&x:a){s+=to_string(x.cost)+":";for(int m:x.mask)s+=to_string(m)+",";s+=';';}return s;}
int f0(const Sig&a,int n){const int full=(1<<n)-1;vector<int>d(1<<n);for(int live=1;live<=full;live++){if(__builtin_popcount((unsigned)live)<=1)continue;int best=INT_MAX/4;for(const A&x:a){bool stalled=false;int worst=0;for(int m:x.mask){int child=live&m;if(child==live){stalled=true;break;}worst=max(worst,d[child]);}if(!stalled)best=min(best,x.cost+worst);}if(best==INT_MAX/4)throw runtime_error("NO_PROGRESS");d[live]=best;}return d[full];}
struct DP {int n,f,b;vector<uint64_t>w;unordered_map<uint64_t,int>mem;size_t cap;
DP(int n_,int f_,size_t maxstates):n(n_),f(f_),b(f+2),w(n),cap(maxstates){w[0]=1;for(int i=1;i<n;i++)w[i]=w[i-1]*b;mem.reserve(10000);}
int value(uint64_t state,const Sig&a){auto it=mem.find(state);if(it!=mem.end())return it->second;uint64_t x=state;int e[13]={},live=0;for(int i=0;i<n;i++){e[i]=x%b;x/=b;if(e[i]<=f)live|=1<<i;}if(__builtin_popcount((unsigned)live)<=1)return 0;if(mem.size()>cap)throw runtime_error("STATE_CAP_REACHED");int best=INT_MAX/4;for(const A&act:a){bool stalled=false;for(int m:act.mask)if((m&live)==live){stalled=true;break;}if(stalled)continue;int worst=0;for(int mask:act.mask){uint64_t next=state;for(int i=0;i<n;i++)if(!(mask&(1<<i))&&e[i]<f+1)next+=w[i];worst=max(worst,value(next,a));if(act.cost+worst>=best)break;}best=min(best,act.cost+worst);}if(best==INT_MAX/4)throw runtime_error("NO_PROGRESS");mem.emplace(state,best);return best;}};
int main(int argc,char**argv){if(argc<3){cerr<<"usage: program window_adj.bin census12 | pair12 u v f | census13\n";return 2;}ifstream f(argv[1],ios::binary);vector<uint8_t> adj((size_t)Q*N*N);f.read((char*)adj.data(),adj.size());if(!f||f.gcount()!=(streamsize)adj.size())throw runtime_error("BAD_FROZEN_ADJACENCY");string mode=argv[2];
if(mode=="census12") {unordered_map<string,pair<int,int>> cached;map<int,int>hist;int count=0;cout<<"u,v,f0,class\n";set<int>base(begin(S10),end(S10));for(int u=0;u<N;u++)if(!base.count(u))for(int v=u+1;v<N;v++)if(!base.count(v)){vector<int>h(begin(S10),end(S10));h.push_back(u);h.push_back(v);Sig a=build(adj,h);string key=sigkey(a);auto it=cached.find(key);int val,cl;if(it==cached.end()){val=f0(a,12);cl=cached.size();cached.emplace(move(key),make_pair(val,cl));}else{val=it->second.first;cl=it->second.second;}cout<<u<<","<<v<<","<<val<<","<<cl<<"\n";hist[val]++;count++;}cerr<<"pairs="<<count<<" signatures="<<cached.size()<<"\n";for(auto[x,y]:hist)cerr<<"f0="<<x<<" count="<<y<<"\n";return 0;}
if(mode=="pair12") {if(argc<6)return 2;int u=stoi(argv[3]),v=stoi(argv[4]),maxf=stoi(argv[5]);vector<int>h(begin(S10),end(S10));h.push_back(u);h.push_back(v);auto a=build(adj,h);cout<<"u,v,f,value,states\n";for(int f=0;f<=maxf;f++){DP s(12,f,8000000);int ans=s.value(0,a);cout<<u<<","<<v<<","<<f<<","<<ans<<","<<s.mem.size()<<"\n";}return 0;}
if(mode=="census13") {set<int>base(begin(S12),end(S12));map<string,pair<vector<int>,int>> cached;cout<<"t,class,f0,f1,f2,f3\n";for(int t=0;t<N;t++)if(!base.count(t)){vector<int>h(begin(S12),end(S12));h.push_back(t);auto a=build(adj,h);auto key=sigkey(a);auto it=cached.find(key);vector<int>vals;int cls;if(it==cached.end()){vals.push_back(f0(a,13));for(int f=1;f<=3;f++){DP s(13,f,3000000);vals.push_back(s.value(0,a));}cls=cached.size();cached.emplace(move(key),make_pair(vals,cls));}else{vals=it->second.first;cls=it->second.second;}cout<<t<<","<<cls;for(int x:vals)cout<<","<<x;cout<<"\n";}cerr<<"classes="<<cached.size()<<"\n";return 0;}return 2;}
